//! Replays the lifecycle's share of the oracle corpus: every case of a kind
//! this crate answers must get the answer upstream's TypeScript gave,
//! compared as text. The cases are read against the installed tree kept
//! under `fixtures/upstream/`. The corpus is regenerated by
//! `tools/oracle/refresh.sh`; nothing here needs upstream or Bun.

use std::fs;
use std::path::Path;

use focus_harness::Harness;
use focus_js::json::stringify;
use focus_lifecycle::oracle::{KINDS, run_case};
use focus_lifecycle::workflow::Workflow;
use focus_workspace::Layout;
use focus_workspace::records::{Invoker, Selection};
use serde_json::{Value, json};

#[test]
fn every_lifecycle_case_gets_upstreams_answer() {
    let fixtures = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures");
    // Nothing is written: the install is read where the fixtures keep it.
    let wf = Workflow::open(
        Layout::new(fixtures.join("upstream/installed/claude"), Harness::Claude),
        Selection {
            space: "default".to_owned(),
            intent: None,
            session_id: None,
            binding: None,
        },
        Invoker::default(),
    )
    .unwrap();
    let dir = fixtures.join("oracle");
    // The corpus is kept by kind: the kinds this crate answers, each in the
    // order it was answered in.
    let read = |part: &str| -> String {
        KINDS
            .iter()
            .map(|kind| fs::read_to_string(dir.join(part).join(format!("{kind}.ndjson"))).unwrap())
            .collect()
    };
    let cases = read("cases");
    let expected = read("expected");
    let cases: Vec<&str> = cases.split('\n').filter(|l| !l.is_empty()).collect();
    let expected: Vec<&str> = expected.split('\n').filter(|l| !l.is_empty()).collect();
    assert_eq!(
        cases.len(),
        expected.len(),
        "the cases and their answers are out of step"
    );

    let (mut windows, mut floored, mut unfloored, mut merged, mut open) = (0, 0, 0, 0, 0);
    let (mut counts, mut refused, mut still_pending, mut closed) = (0, 0, 0, 0);
    let (mut ambiguous, mut started_again, mut recovered, mut in_a_bolt) = (0, 0, 0, 0);
    let (mut snapshots, mut fingerprinted, mut whole, mut appended) = (0, 0, 0, 0);
    let (mut two_views, mut converted, mut came_after) = (0, 0, 0);
    let (mut current, mut unreadable, mut replaceable) = (0, 0, 0);
    let (mut retried, mut unrecordable) = (0, 0);
    let (mut evidence, mut in_order, mut not_owed) = (0, 0, 0);
    let (mut let_through, mut missing, mut stale) = (0, 0, 0);
    let (mut kept, mut written, mut read_back, mut unverified) = (0, 0, 0, 0);
    let (mut collided, mut behind_a_link, mut told_paths, mut earlier_place) = (0, 0, 0, 0);
    let (mut receipts, mut standing, mut fallen, mut waiting) = (0, 0, 0, 0);
    let (mut moved_source, mut let_pass, mut started_from) = (0, 0, 0);
    let (mut refusals, mut for_the_person, mut as_a_command, mut no_way_now) = (0, 0, 0, 0);
    let (mut thrown, mut sentences, mut named_a_command, mut asked_which) = (0, 0, 0, 0);
    let mut resettable = 0;
    let mut differing = Vec::new();
    for (line, want) in cases.iter().zip(&expected) {
        let case: Value = focus_js::json::parse(line).unwrap();
        let kind = case["kind"].as_str().unwrap_or_default();
        if !KINDS.contains(&kind) {
            continue;
        }
        // A case with a link or a second name in it needs a platform where a
        // link is a file and a file says how many names it has.
        let has = |key: &str| case[key].as_object().is_some_and(|map| !map.is_empty());
        // And one marked `posix` rests on what such a host says of a path
        // that goes through a file.
        if cfg!(windows) && (has("links") || has("hard") || case["posix"] == true) {
            continue;
        }
        let out = run_case(&wf, &case);
        let some = |key: &str| out[key].as_array().is_some_and(|list| !list.is_empty());
        if kind == "guard_refusal" {
            // The ways on of a guard that refuses: put to the person, run as
            // a command, none that can be done now, and the operation that
            // names what none may.
            refusals += 1;
            let remedies = out["remedies"].as_array().cloned().unwrap_or_default();
            let any =
                |key: &str, value: &Value| remedies.iter().any(|remedy| remedy[key] == *value);
            for_the_person += usize::from(any("requiresHuman", &json!(true)));
            as_a_command += usize::from(any("interaction", &json!("command")));
            no_way_now +=
                usize::from(out.get("error").is_none() && !any("executableNow", &json!(true)));
            thrown += usize::from(out["error"] == "Invalid guard recovery operation");
        } else if kind == "recovery_guidance" {
            // The sentence a prose refusal ends with: a way on, the unit's
            // own command, or a question for the person.
            let sentence = out["guidance"].as_str().unwrap_or_default();
            sentences += usize::from(!sentence.is_empty());
            named_a_command += usize::from(sentence.contains("When the person says so, run `"));
            asked_which += usize::from(sentence.starts_with("Ask the person"));
            thrown += usize::from(out["guidance"]["error"].is_string());
            resettable += usize::from(out["reset"] == true);
        } else if kind == "review_receipts" {
            // The reviews that still stand: a verdict for the stage or a
            // unit, one a later write made stale, a request that waits, the
            // source moved since, a change the policy let through, and the
            // baseline read back.
            receipts += 1;
            assert!(out.get("error").is_none(), "{}: {out}", case["id"]);
            let any = |value: &Value| value.as_array().is_some_and(|list| !list.is_empty());
            standing += usize::from(out["stage"][0].is_string() || any(&out["units"]["verdicts"]));
            fallen += usize::from(out["stage"][1] == true || any(&out["units"]["stale"]));
            waiting += usize::from(any(&out["awaiting"]));
            moved_source += usize::from(out["source"][2] == true);
            let_pass += usize::from(any(&out["accepted"]));
            started_from += usize::from(out["baseline"].is_array());
        } else if kind == "source_snapshot" {
            // The two snapshots of a stage: written, read back under the
            // row's fingerprint, refused when the bytes are not the ones it
            // names, never written over or through a link, and told as
            // paths.
            kept += 1;
            written += usize::from(out["first"][0].is_string() && out["first"][1] == true);
            read_back += usize::from(out["baseline"][0].is_array());
            unverified += usize::from(out["first"][0].is_string() && out["baseline"][0].is_null());
            let refusal = out["second"][0]["error"].as_str().unwrap_or_default();
            collided += usize::from(refusal.starts_with("Source snapshot address collision"));
            behind_a_link += usize::from(refusal.ends_with("already-trusted one."));
            told_paths += usize::from(out["told"].as_str().is_some_and(|told| !told.is_empty()));
            earlier_place += usize::from(out["after"].as_object().is_some_and(|files| {
                files
                    .keys()
                    .any(|name| name.starts_with(".focus-source-review/"))
            }));
        } else if kind == "summary_evidence" {
            evidence += 1;
            assert!(out.get("error").is_none(), "{}: {out}", case["id"]);
            in_order += usize::from(out["ok"] == true && out["required"] == true);
            not_owed += usize::from(out["required"] == false);
            let_through += usize::from(
                out["accepted"]
                    .as_array()
                    .is_some_and(|list| !list.is_empty()),
            );
            missing += usize::from(out["coverage"] == "missing");
            stale += usize::from(out["coverage"] == "stale");
        } else if kind == "review_snapshot" {
            snapshots += 1;
            fingerprinted += usize::from(out["fingerprint"].is_string());
            let taken = &out["snapshot"];
            whole += usize::from(taken.is_object());
            appended += usize::from(taken["appendix"][0].as_u64().is_some_and(|len| len > 0));
            two_views += usize::from(
                taken["bodies"]
                    .as_array()
                    .is_some_and(|views| views.len() == 2),
            );
            converted += usize::from(taken["raw"][0].is_string());
            came_after += usize::from(out["told"][1][0][1] == true);
            assert!(out.get("error").is_none(), "{}: {out}", case["id"]);
            // What can be done with a pending request: three flags for
            // each way of asking each request (44 or 28 of a stage that
            // writes the workspace, 12 of another; two ways, and a third
            // for the first eight), then four flags for each request as the
            // oldest pending one.
            let flags = |key: &str| out["pending"][key].as_str().unwrap_or_default().as_bytes();
            let (currency, status) = (flags("currency"), flags("status"));
            assert!(
                matches!(
                    (currency.len(), status.len()),
                    (288, 176) | (192, 112) | (96, 48)
                ),
                "{}: {out}",
                case["id"]
            );
            let any = |rows: &[u8], width: usize, wanted: &[u8]| {
                rows.chunks(width).any(|row| row == wanted)
            };
            current += usize::from(any(currency, 3, b"111"));
            unreadable += usize::from(any(currency, 3, b"100"));
            replaceable += usize::from(any(status, 4, b"0001"));
            retried += usize::from(any(status, 4, b"1010"));
            unrecordable += usize::from(any(status, 4, b"1100"));
        } else if kind == "review_accounting" {
            counts += 1;
            refused += usize::from(out.get("error").is_some());
            let waiting = out["pending"].as_array().map_or(0, Vec::len) as u64;
            let asked = out["requests"].as_u64().unwrap_or_default();
            still_pending += usize::from(waiting > 0);
            closed += usize::from(asked > waiting);
            ambiguous += usize::from(out["ambiguity"].is_string());
            started_again += usize::from(out["budgeted"].as_u64().unwrap_or_default() < asked);
            recovered += usize::from(out["recovery"][1] == true);
            in_a_bolt += usize::from(out["bolt"][0] == true);
        } else {
            windows += 1;
            floored += usize::from(out["floor"].as_i64().is_some_and(|floor| floor >= 0));
            unfloored += usize::from(out["floor"] == -1);
            merged += usize::from(some("merged"));
            open += usize::from(some("open"));
        }
        let mut out = out;
        let mut want = (*want).to_owned();
        if kind == "summary_evidence" && cfg!(windows) {
            // A refusal's sentence names files by their path and commands
            // as this platform's shell writes them: the rest of the answer
            // is compared.
            if let Some(answer) = out.as_object_mut() {
                answer.remove("message");
            }
            let mut wanted: Value = focus_js::json::parse(&want).unwrap();
            if let Some(answer) = wanted["out"].as_object_mut() {
                answer.remove("message");
            }
            want = stringify(&wanted);
        }
        let got = stringify(&json!({ "id": case["id"], "out": out }));
        if got != want {
            differing.push(format!(
                "{}\n  upstream: {want}\n  focus:    {got}",
                case["id"]
            ));
        }
    }
    // Enough cases, and enough of them on each side of every answer.
    assert!(
        windows >= 1900 && floored >= 1400 && unfloored >= 400,
        "{windows} {floored} {unfloored}"
    );
    assert!(merged >= 280 && open >= 580, "{merged} {open}");
    assert!(
        cfg!(windows) || (counts >= 1150 && refused >= 40 && still_pending >= 500 && closed >= 250),
        "{counts} {refused} {still_pending} {closed}"
    );
    assert!(
        ambiguous >= 200 && started_again >= 20 && recovered >= 40 && in_a_bolt >= 20,
        "{ambiguous} {started_again} {recovered} {in_a_bolt}"
    );
    assert!(
        cfg!(windows)
            || (snapshots >= 1250
                && fingerprinted >= 900
                && snapshots - fingerprinted >= 300
                && whole >= 640),
        "{snapshots} {fingerprinted} {whole}"
    );
    assert!(
        cfg!(windows)
            || (appended >= 210 && two_views >= 150 && converted >= 240 && came_after >= 210),
        "{appended} {two_views} {converted} {came_after}"
    );
    assert!(
        cfg!(windows)
            || (current >= 650
                && unreadable >= 240
                && replaceable >= 650
                && retried >= 240
                && unrecordable >= 650),
        "{current} {unreadable} {replaceable} {retried} {unrecordable}"
    );
    assert!(
        evidence >= 1350 && in_order >= 240 && not_owed >= 120 && let_through >= 60,
        "{evidence} {in_order} {not_owed} {let_through}"
    );
    assert!(missing >= 380 && stale >= 600, "{missing} {stale}");
    assert!(
        receipts >= 1500 && standing >= 600 && fallen >= 250 && waiting >= 450,
        "{receipts} {standing} {fallen} {waiting}"
    );
    assert!(
        moved_source >= 100 && let_pass >= 300 && started_from >= 240,
        "{moved_source} {let_pass} {started_from}"
    );
    assert!(
        kept >= if cfg!(windows) { 450 } else { 550 }
            && written >= 400
            && read_back >= 300
            && unverified >= 100,
        "{kept} {written} {read_back} {unverified}"
    );
    assert!(
        collided >= 100
            && (cfg!(windows) || behind_a_link >= 30)
            && told_paths >= 250
            && earlier_place >= 100,
        "{collided} {behind_a_link} {told_paths} {earlier_place}"
    );
    assert!(
        refusals >= 2700 && for_the_person >= 2400 && as_a_command >= 1500 && no_way_now >= 60,
        "{refusals} {for_the_person} {as_a_command} {no_way_now}"
    );
    assert!(
        sentences >= 2000 && named_a_command >= 40 && asked_which >= 50 && resettable >= 500,
        "{sentences} {named_a_command} {asked_which} {resettable}"
    );
    assert!(thrown >= 90, "{thrown}");
    assert!(
        differing.is_empty(),
        "{} lifecycle cases differ from upstream; first:\n{}",
        differing.len(),
        differing
            .iter()
            .take(3)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
